/*
 * P3R Native Android AOT Runtime: Guest CPU Implementation
 * Matches Recomp ABI v2 (Bloodborne-Android upstream cpu/guest_cpu_aot.cpp)
 */

#include "guest_cpu.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// External dispatch table generated by p3r_recomp.py
extern const size_t g_bbr_unit_count;
extern const RecompUnit g_bbr_units[];

void bbr_init_guest_state(GuestState* state, void* stack_base, size_t stack_size) {
    if (!state) return;
    memset(state, 0, sizeof(GuestState));

    // Initialize 16-byte aligned guest stack pointer
    if (stack_base && stack_size > 64) {
        uintptr_t sp = (uintptr_t)stack_base + stack_size - 32;
        sp &= ~0xF; // 16-byte alignment (SysV AMD64 requirement)
        state->gregs[GUEST_RSP] = (uint64_t)sp;
        state->gregs[GUEST_RBP] = (uint64_t)sp;
    }
}

void bbr_dispatch(GuestState* state, uint64_t target_vaddr) {
    if (!state) return;
    state->rip = target_vaddr;

    bbr_func_t target_func = bbr_lookup(target_vaddr);
    if (target_func) {
        target_func(state);
    } else {
        // Missing entry diagnostic matching discover.cpp / miss logs
        fprintf(stderr, "[P3R-AOT MISS] Un-recompiled virtual address: 0x%llx\n", (unsigned long long)target_vaddr);
        bbr_trap(state, BBR_TRAP_MISS);
    }
}

void bbr_trap(GuestState* state, uint64_t trap_code) {
    if (!state) return;
    fprintf(stderr, "[P3R-AOT TRAP] Execution halted. RIP=0x%llx, TrapCode=0x%llx\n",
            (unsigned long long)state->rip, (unsigned long long)trap_code);

    if (trap_code & BBR_TRAP_MISS) {
        fprintf(stderr, "  Reason: Address not found in AOT dispatch table (requires extra-entries discovery).\n");
    } else if (trap_code & BBR_TRAP_UNLIFTABLE) {
        fprintf(stderr, "  Reason: Unliftable opcode or division-by-zero violation.\n");
    } else {
        fprintf(stderr, "  Reason: Unsupported system instruction or console privilege call.\n");
    }
}

uint64_t bbr_run_entry(GuestState* state, uint64_t entry_vaddr) {
    if (!state) return 0;
    bbr_dispatch(state, entry_vaddr);
    // SysV AMD64 return value convention: return register is RAX
    return state->gregs[GUEST_RAX];
}
